 */

#include "../dependence/controlController.hpp"
#include <iostream>
#include <cmath>

/**
 * @brief 比较两个双精度浮点数是否近似相等
 * @en_name assertDoubleEqual
 * @cn_name 断言双精度相等
 * @type 函数
 * @param expected 期望值
 * @param actual 实际值
 * @param tolerance 容差
 * @retval int 1-通过，0-失败
 * @granularity 原子函数
 * @tag_level1 测试工具
 * @tag_level2 断言
 * @version 1.0
 * @date 2023-10-27
 * @author System
 */
static int assertDoubleEqual(double expected, double actual, double tolerance)
{
    double diff = expected - actual;
    /* 获取绝对值 */
    double absDiff = diff;
    if (diff < 0.0) {
        absDiff = -diff;
    }

    int result = 0;
    if (absDiff <= tolerance) {
        result = 1;
    }

    return result;
}

/**
 * @brief 打印测试结果
 * @en_name printTestResult
 * @cn_name 打印测试结果
 * @type 函数
 * @param caseName 测试用例名称
 * @param passed 是否通过
 * @retval void
 * @granularity 原子函数
 * @tag_level1 测试工具
 * @tag_level2 输出
 * @version 1.0
 * @date 2023-10-27
 * @author System
 */
static void printTestResult(const char* caseName, int passed)
{
    if (passed == 1) {
        std::cout << "[PASS] " << caseName << std::endl;
    } else {
        std::cout << "[FAIL] " << caseName << std::endl;
    }
}

/**
