/**
 * @brief 两点欧几里得距离计算
 * @details 计算二维平面上两点之间的直线距离
 * @en_name get2Dis
 * @cn_name 两点距离计算
 * @type 函数
 * @param x1 第一个点的X坐标 [m]
 * @param x2 第二个点的X坐标 [m]
 * @param y1 第一个点的Y坐标 [m]
 * @param y2 第二个点的Y坐标 [m]
 * @retval double 两点间的欧几里得距离 [m]
 * @granularity 原子函数
 * @tag_level1 基础数学
 * @tag_level2 距离计算
 * @formula \sqrt{(x_1-x_2)^2 + (y_1-y_2)^2}
 * @version 1.0
 * @date 2023-10-27
 * @author System
 */
static inline double get2Dis(double x1, double x2, double y1, double y2)
{
    double deltaX = x1 - x2;
    double deltaY = y1 - y2;
    double distSq = deltaX * deltaX + deltaY * deltaY;
    double distance = sqrt(distSq);
    return distance;
}

