        isValid = ERROR_INPUT_EMPTY;
        return isValid;
    }

    if (size <= 2) {
        isValid = ERROR_INPUT_SIZE;
        return isValid;
    }

    prevT = points[0].t;

    for (i = 1; i < size; i = i + 1) {
        dt = points[i].t - prevT;
        if (dt <= 0.0001) { 
            isValid = ERROR_INPUT_DISCONTINUOUS;
            return isValid;
        }
        if (points[i].v < 0.0) {
            isValid = ERROR_INPUT_INVALID;
            return isValid;
        }
        prevT = points[i].t;
    }

    isValid = ERROR_OK;
    return isValid;
}

