static void performL2SmoothingStep(const STgraphOptParam* param, const PlanningTrajectory* inputTrajectory, PlanningTrajectory* outputTrajectory, double* change) {
    int32_t i = 0;
    int32_t size = 0;
    double vTemp = 0.0;
    double vNew = 0.0;
    double diff = 0.0;
    double smoothTerm = 0.0;
    double dataTerm = 0.0;
