/**
  @brief 检查输入数据有效性
  @en_name checkInputValidity
  @cn_name 输入有效性检查
  @type 原子函数
  @param[in] input 优化输入
  @retval int32_t 错误码
  @granularity 函数
  @tag_level1 规划
  @tag_level2 速度规划
  @version 1.0.0
  @date 2023-10-27
  @author AI_Coder
*/
static int32_t checkInputValidity(const STgraphOptInput* input) {
    int32_t isValid = 0;
    int32_t i = 0;
    double dt = 0.0;
    double prevT = 0.0;
    PlanningPoint* points = NULL;
    int32_t size = 0;

    points = input->trajectory.planningPoints;
    size = input->trajectory.size;

    if (points == NULL) {
        isValid = ERROR_INPUT_EMPTY;
        return isValid;
    }

    if (size <= 2) {
        isValid = ERROR_INPUT_SIZE;
        return isValid;
    }

    prevT = points[0].t;

    for (i = 1; i < size; i = i + 1) {
        dt = points[i].t - prevT;
        if (dt <= 0.0001) { 
            isValid = ERROR_INPUT_DISCONTINUOUS;
            return isValid;
        }
        if (points[i].v < 0.0) {
            isValid = ERROR_INPUT_INVALID;
            return isValid;
        }
        prevT = points[i].t;
    }

    isValid = ERROR_OK;
    return isValid;
}

/**
