static double bSplineIteration(const STgraphOptParam* param, const PlanningTrajectory* refTraj, PlanningTrajectory* currTraj) {
    double maxChange = 0.0; /* 最大变化量 */
    int32_t size = currTraj->size; /* 轨迹点数量 */
    int32_t i = 0; /* 循环索引 */

