        else if (param->algoType == ALGO_TYPE_CUBIC) {
            change = cubicCurveIteration(param, refTraj, optTraj);
        } 
        else {
            return ERR_ALGO_UNSUPPORTED;
        }

        if (change < param->tolerance) {
            hasConverged = 1;
        }

        if (1 == hasConverged) {
            break;
        }

        iter = iter + 1;
    }

    return ERR_SUCCESS;
}

