static void stepL2Smooth(const STgraphOptParam* param, const PlanningTrajectory* refTraj, PlanningTrajectory* currTraj, double* maxChange) {
    int i = 0; /**< 循环索引 */
    int size = 0; /**< 轨迹大小 */
