    OptStatus checkStatus = OPT_SUCCESS; /**< 检查状态 */
    OptStatus initStatus = OPT_SUCCESS; /**< 初始化状态 */
    OptStatus optStatus = OPT_SUCCESS; /**< 优化状态 */

    /* 1. 输入合法性检查 */
