    if (checkStatus != OPT_SUCCESS) {
        return checkStatus;
    }

    /* 2. 生成初始猜测轨迹 */
    initStatus = generateInitialGuess(input, &(output->trajectory));
    if (initStatus != OPT_SUCCESS) {
        return initStatus;
    }

    /* 3. 执行迭代优化 */
    optStatus = runOptimizationLoop(param, input, &(output->trajectory));

    return optStatus;
