    tPrev = input->trajectory.points[0].t;
    for (i = 1; i < input->trajectory.size; i = i + 1) {
        if (input->trajectory.points[i].t <= tPrev) {
            isContinuous = 0;
        }
        tPrev = input->trajectory.points[i].t;
        if (isContinuous == 0) {
            break;
        }
    }

    if (isContinuous == 0) {
        return OPT_ERROR_INVALID;
    }

    return OPT_SUCCESS;
}

