    double vTemp = 0.0; /**< 临时速度变量 */
    double diff = 0.0; /**< 速度差值 */
    double fitTerm = 0.0; /**< 拟合项 */
    double smoothTerm = 0.0; /**< 平滑项 */
    double localChange = 0.0; /**< 局部变化量 */

    size = currTraj->size;
    *maxChange = 0.0;

    for (i = 1; i < size - 1; i = i + 1) {
