            ret = -1;
        }
    }

    // 4. 解析排序顺序参数
    if (0 == ret) {
        if (NULL != orderStr) {
            // 比较是否为降序
            int cmpDesc = strcmp(orderStr, "desc");
            if (0 == cmpDesc) {
                isAscending = 0;
            } else {
                // 如果不是 desc，则检查是否为 asc，否则报错
                int cmpAsc = strcmp(orderStr, "asc");
