    int allocSize = 0; /**< 分配大小 */

    allocSize = input->trajectory.size;
    initTraj->points = (PlanningPoint*)malloc(sizeof(PlanningPoint) * allocSize);

    if (initTraj->points == NULL) {
        return OPT_ERROR_NULL;
