/**
  @brief 优化参数结构体
  @field algoType AlgoType 算法类型选择
  @field maxIterations int 最大迭代次数
  @field errorThreshold double 误差阈值
  @field weightData double 数据拟合权重
  @field weightSmooth double 平滑性权重
  @field tolerance double 收敛容差（兼容旧版接口）
*/
typedef struct {
