    int i = 0; /**< 循环索引 */
    int size = 0; /**< 轨迹大小 */
    double vPrev = 0.0; /**< 前一点速度 */
    double vNext = 0.0; /**< 后一点速度 */
    double vRef = 0.0; /**< 参考速度 */
    double vCurr = 0.0; /**< 当前速度 */
