 * @retval MatchResult 匹配结果
 * @tag_level1 Algorithm
 * @version 1.0.0
 * @date 2023-10-27
 * @author System
 */
MatchResult findNearestTrajPoint(State state, const Traj traj);

#ifdef __cplusplus
}
#endif

#endif // TRAJ_MATCHER_H
