	}
	cout << endl;

	if (origin == destination)
	{
		path.push_back(destination);
		return path;
	}

	road* result = findPath(origin, destination);
	int temp = result->father;
	path.push_back(destination);
	path.push_front(temp);
	while (temp != origin)
	{
		temp = roadList[temp].father;
		path.push_front(temp);
	}
	if (!openList.empty())openList.pop();
