    SpeedModelParam param2{};
    SpeedModelInput input2{distance};
    SpeedModelOutput output2{0};
    speedModel(param2, input2, output2);
    trajectory.planningPoints[i].v = output2.speed;

    if (trajectory.planningPoints[i].v > 0){
