      GetDistanceInput input3{
        trajectory.planningPoints[i].x,
        trajectory.planningPoints[i].y,
        trajectory.planningPoints[i+1].x,
        trajectory.planningPoints[i+1].y
      };
      GetDistanceOutput output3{0};
