/**
 * @brief 计算两点间欧氏距离的平方
 * @en_name calcSquareDist
 * @cn_name 计算距离平方
 * @type 函数
 * @param dx 输入参数，X方向差值，单位：m
 * @param dy 输入参数，Y方向差值，单位：m
 * @param sqDist 输出参数，距离的平方，单位：m^2
 * @retval int 执行结果，0表示成功
 * @granularity 原子函数
 * @tag_level1 Math
 * @tag_level2 Geometry
 * @formula $d^2 = dx^2 + dy^2$
 * @version 1.0
 * @date 2023-10-27
 * @author AIAssistant
 */
int calcSquareDist(double dx, double dy, double* sqDist)
{
    double tempDx = dx * dx; // 计算X方向差值的平方
    double tempDy = dy * dy; // 计算Y方向差值的平方
    *sqDist = tempDx + tempDy; // 求和得到距离平方
    return 0;
}

/**
 * @brief 查找最近轨迹点索引及距离
 * @en_name findNearestPoint
 * @cn_name 查找最近轨迹点
 * @type 函数
 * @param stateX 输入参数，当前状态X坐标，单位：m
 * @param stateY 输入参数，当前状态Y坐标，单位：m
 * @param trajXs 输入参数，轨迹点X坐标数组，单位：m
 * @param trajYs 输入参数，轨迹点Y坐标数组，单位：m
 * @param pointCount 输入参数，轨迹点数量
 * @param index 输出参数，最近轨迹点的索引，轨迹为空时为-1
 * @param distance 输出参数，最近点的欧氏距离，单位：m
 * @retval int 执行结果，0表示成功，-1表示失败
 * @granularity 原子函数
 * @tag_level1 Control
 * @tag_level2 Trajectory
 * @formula $d = \min(\sqrt{(x_i - x)^2 + (y_i - y)^2})$
 * @version 1.0
 * @date 2023-10-27
 * @author AIAssistant
 */
int findNearestPoint(double stateX, double stateY, const double* trajXs, const double* trajYs, int pointCount, int* index, double* distance)
{
    int i = 0; // 循环变量
    int result = 0; // 中间结果变量
    double minSqDist = 0.0; // 最小距离平方
    double currSqDist = 0.0; // 当前距离平方
    double currDx = 0.0; // 当前X差值
    double currDy = 0.0; // 当前Y差值
    int nearestIndex = -1; // 最近点索引

    // 检查输入指针有效性
    if ((trajXs == 0) || (trajYs == 0) || (index == 0) || (distance == 0))
    {
        return -1;
    }

    // 处理轨迹为空的情况
    if (pointCount <= 0)
    {
        *index = -1;
        *distance = 0.0;
        return 0;
    }

    // 初始化最小距离为最大值
    minSqDist = DBL_MAX;

    // 遍历轨迹点
    i = 0;
    while (i < pointCount)
    {
        // 计算坐标差值
        currDx = trajXs[i] - stateX;
        currDy = trajYs[i] - stateY;

        // 计算距离平方
        calcSquareDist(currDx, currDy, &currSqDist);

        // 更新最小距离和索引
        if (currSqDist < minSqDist)
        {
            minSqDist = currSqDist;
            nearestIndex = i;
        }

        // 循环变量自增（规范要求展开为显式赋值）
        i = i + 1;
    }

    // 输出结果
    *index = nearestIndex;

    // 计算并返回欧氏距离（开方）
    *distance = sqrt(minSqDist);

    return 0;
}
