    astarInstance.initRoad(3, 0.0, 0.0, 10.0, 0.0, 10.0);
    astarInstance.initRoad(6, 10.0, 0.0, 20.0, 0.0, 10.0);
    astarInstance.initLink(3, 6);

    // 执行路径规划
