/**
 * @brief 计算两点间欧氏距离的平方
 * @details 避免开方运算以提高性能，在比较大小等价
 * 
 * @param dx [IN] X方向差值
 * @param dy [IN] Y方向差值
 * @retval double 距离的平方
 * @tag_level2 Atomic
 * @version 1.0.0
 * @date 2023-10-27
 * @author System
 */
static double calcSquaredDist(double dx, double dy)
{
    double dist_sq = 0.0; /* 距离平方 */
    dist_sq = dx * dx;
    dist_sq = dist_sq + (dy * dy);
    return dist_sq;
}

/**
 * @brief 查找最近轨迹点（复合函数）
 * @details 遍历轨迹点，计算欧氏距离，返回最小距离对应的索引和距离
 * 
 * @param state [IN] 输入状态
 * @param traj [IN] 输入轨迹
 * @retval MatchResult 匹配结果
 * @tag_level1 Composite
 * @version 1.0.0
 * @date 2023-10-27
 * @author System
 */
MatchResult findNearestTrajPoint(State state, const Traj traj)
{
    MatchResult result; /* 返回结果 */
    int i = 0; /* 循环变量 */
    int traj_count = 0; /* 轨迹点总数 */
    TrajPoint current_point; /* 当前循环中的轨迹点 */
    double diff_x = 0.0; /* X坐标差值 */
    double diff_y = 0.0; /* Y坐标差值 */
    double current_dist_sq = 0.0; /* 当前点距离平方 */
    double min_dist_sq = 0.0; /* 最小距离平方 */
    int best_index = -1; /* 最近点索引 */
    double best_distance = 0.0; /* 最近点距离 */
    int is_empty = 0; /* 轨迹是否为空的标志 */

    /* 初始化返回值 */
    result.index = -1;
    result.distance = -1.0;

    /* 检查轨迹是否为空 */
    traj_count = traj.count;
    is_empty = (traj_count <= 0);

    if (is_empty) {
        result.index = -1;
        result.distance = 0.0;
        return result;
    }

    /* 初始化最小距离为极大值 */
    min_dist_sq = DBL_MAX;

    /* 遍历轨迹点 */
    for (i = 0; i < traj_count; i = i + 1) {
        /* 获取当前点 */
        current_point = traj.points[i];

        /* 计算坐标差值 */
        diff_x = current_point.x - state.x;
        diff_y = current_point.y - state.y;

        /* 计算距离平方 */
        current_dist_sq = calcSquaredDist(diff_x, diff_y);

        /* 比较并更新最小值 */
        if (current_dist_sq < min_dist_sq) {
            min_dist_sq = current_dist_sq;
            best_index = i;
        }
    }

    /* 计算最终欧氏距离 */
    best_distance = std::sqrt(min_dist_sq);

    /* 填充结果 */
    result.index = best_index;
    result.distance = best_distance;

    return result;
}

/**
 * @brief 主函数入口
 * @details 演示 findNearestTrajPoint 函数的调用与结果输出
 * @return int 程序退出码
 * @version 1.0.0
 * @date 2023-10-27
 * @author System
 */
int main() {
    /* 定义测试状态 */
    State testState;
    testState.x = 1.5;
    testState.y = 1.5;

    /* 定义测试轨迹点数据 */
    const int pointNum = 3;
    TrajPoint trajDataArray[3];

    /* 初始化轨迹点1 */
    trajDataArray[0].x = 0.0;
    trajDataArray[0].y = 0.0;
    trajDataArray[0].t = 0.0;
    trajDataArray[0].v = 5.0;

    /* 初始化轨迹点2 */
    trajDataArray[1].x = 2.0;
    trajDataArray[1].y = 2.0;
    trajDataArray[1].t = 1.0;
    trajDataArray[1].v = 5.5;

    /* 初始化轨迹点3 */
    trajDataArray[2].x = 3.0;
    trajDataArray[2].y = 3.0;
    trajDataArray[2].t = 2.0;
    trajDataArray[2].v = 6.0;

    /* 构造轨迹对象 */
    Traj testTraj;
    testTraj.points = trajDataArray;
    testTraj.count = pointNum;

    /* 调用匹配函数 */
    MatchResult result = findNearestTrajPoint(testState, testTraj);

    /* 输出结果 */
    std::cout << "Nearest Index: " << result.index << std::endl;
    std::cout << "Euclidean Distance: " << std::fixed << std::setprecision(4) << result.distance << std::endl;

    /* 测试空轨迹情况 */
    Traj emptyTraj;
    emptyTraj.points = NULL;
    emptyTraj.count = 0;
    MatchResult emptyResult = findNearestTrajPoint(testState, emptyTraj);
    std::cout << "Empty Traj Index: " << emptyResult.index << std::endl;

    return 0;
}

