void Astar::initRoad(int id, double xStart, double yStart, double xEnd, double yEnd, double length) {
    int index = id; // 简化处理，直接使用ID作为索引
    if (index < 100) {
        roadList[index].id = id;
        roadList[index].xBegin = xStart;
        roadList[index].yBegin = yStart;
