		double xStart = it->lanes.begin()->gaussRoadPoints.begin()->GaussX;
		double yStart = it->lanes.begin()->gaussRoadPoints.begin()->GaussY;
		double xEnd = it->lanes.begin()->gaussRoadPoints.rbegin()->GaussX;
