    // 验证结果 (最近点应为索引0，距离sqrt(17)约等于4.12，或索引1距离6.0，最近应为0)
    if (status == 0) {
        std::cout << "Test Normal: Success. Index: " << foundIndex << ", Dist: " << foundDist << std::endl;
