    if (isValid == 1) {
        p = (a + b + c) * 0.5;
        areaSquared = p * (p - a) * (p - b) * (p - c);
        /* 防止浮点误差导致负数 */
        if (areaSquared < 0.0) {
            areaSquared = 0.0;
